<?php

namespace App\Service\Gw2;

/**
 * Data of the legendary trees, read from data/gw2/:
 * - legendary_recipes.json: generated by app:gw2:import-legendary-recipes (official API + Mystic Forge)
 * - legendary_achievements.json: generated too, the in-game collections of each legendary
 * - legendary_hints.json: generated too, how to get items, from the Le Bus Magique guides
 * - legendary_sources.json: written by hand, wins over the generated hints: vendor prices in
 *   currencies, and how to get the items that have no recipe (map completion, WvW...)
 */
class Gw2RecipeBook
{
    private ?array $recipes = null;
    private ?array $sources = null;
    private array $hints = [];
    private array $achievements = [];

    public function __construct(private string $dataDir)
    {
    }

    /** @return array{source: string, output: int, ingredients: array}|null */
    public function recipe(int $itemId): ?array
    {
        $this->load();

        // "leaf": obtained as is in game, its crafting recipe must not be expanded
        if (!empty($this->sources['items'][$itemId]['leaf'])) {
            return null;
        }

        return $this->recipes[$itemId] ?? $this->vendorRecipe($itemId);
    }

    /** @return int[] every currency a recipe or a merchant asks for */
    public function allCurrencyIds(): array
    {
        $this->load();
        $ids = [];
        $recipes = array_merge(array_values($this->recipes), array_column(array_column($this->sources['items'], 'vendor'), null));
        foreach ($recipes as $recipe) {
            foreach ($recipe['ingredients'] ?? [] as $ingredient) {
                if ('currency' === $ingredient['type']) {
                    $ids[] = $ingredient['id'];
                }
            }
        }

        return array_values(array_unique($ids));
    }

    /** How to get an item that can't be bought or crafted, in French, or null */
    public function hint(int $itemId): ?string
    {
        $this->load();

        return $this->sources['items'][$itemId]['hint'] ?? $this->hints[$itemId]['hint'] ?? null;
    }

    /** How to earn a currency (karma, dungeon tokens...), in French, or null */
    public function currencyHint(int $currencyId): ?string
    {
        $this->load();

        return $this->sources['currencies'][$currencyId]['hint'] ?? null;
    }

    /** Where a generated hint comes from (a guide URL), null for hand-written ones */
    public function hintSource(int $itemId): ?string
    {
        $this->load();

        return isset($this->sources['items'][$itemId]['hint']) ? null : ($this->hints[$itemId]['source'] ?? null);
    }

    /** @return array{collection: ?int, precursor: int[]} in-game collections of a legendary */
    public function achievements(int $legendaryId): array
    {
        $this->load();

        return $this->achievements[$legendaryId] ?? ['collection' => null, 'precursor' => []];
    }

    /** @return int[] every achievement linked to a legendary of the catalogue */
    public function allAchievementIds(): array
    {
        $this->load();
        $ids = [];
        foreach ($this->achievements as $links) {
            $ids = array_merge($ids, array_filter([$links['collection']]), $links['precursor']);
        }

        return array_values(array_unique($ids));
    }

    public function all(): array
    {
        $this->load();

        return $this->recipes;
    }

    // Items bought from a merchant with a currency (e.g. Bloodstone Shard for 200 Spirit Shards)
    private function vendorRecipe(int $itemId): ?array
    {
        $vendor = $this->sources['items'][$itemId]['vendor'] ?? null;
        if (!$vendor) {
            return null;
        }

        return [
            'source' => 'vendor',
            'output' => $vendor['output'] ?? 1,
            'ingredients' => $vendor['ingredients'],
        ];
    }

    private function load(): void
    {
        if (null !== $this->recipes) {
            return;
        }
        $recipes = $this->readJson('legendary_recipes.json');
        $this->recipes = [];
        foreach ($recipes['recipes'] ?? [] as $id => $recipe) {
            $this->recipes[(int) $id] = $recipe;
        }
        $sources = $this->readJson('legendary_sources.json');
        $this->sources = ['items' => [], 'currencies' => []];
        foreach ($sources['items'] ?? [] as $id => $source) {
            $this->sources['items'][(int) $id] = $source;
        }
        foreach ($sources['currencies'] ?? [] as $id => $currency) {
            $this->sources['currencies'][(int) $id] = $currency;
        }
        foreach ($this->readJson('legendary_hints.json')['items'] ?? [] as $id => $hint) {
            $this->hints[(int) $id] = $hint;
        }
        foreach ($this->readJson('legendary_achievements.json')['legendaries'] ?? [] as $id => $links) {
            $this->achievements[(int) $id] = $links;
        }
    }

    private function readJson(string $file): array
    {
        $path = $this->dataDir.'/'.$file;

        return is_file($path) ? (json_decode(file_get_contents($path), true) ?? []) : [];
    }
}
